#!/bin/sh
# Hermetic stand-in for the ffmpeg executable used by the voice preparation
# boundary eval. It accepts the production argument shape, verifies the OGG
# container and Opus identification header, then emits a bundled, valid tiny
# AAC/M4A stream. It deliberately fails malformed input with a nonzero exit.

input=""
output=""

while [ "$#" -gt 0 ]; do
    if [ "$1" = "-i" ]; then
        shift
        [ "$#" -gt 0 ] || exit 64
        input="$1"
    fi
    output="$1"
    shift
done

[ -n "$input" ] && [ -n "$output" ] || exit 64
[ "$(dd if="$input" bs=4 count=1 2>/dev/null)" = "OggS" ] || exit 65
LC_ALL=C grep -q 'OpusHead' "$input" || exit 66

# A checked 250ms mono AAC/M4A stream. Keeping it in the fixture means the eval
# exercises the production Process runner without requiring a host converter.
base64 -D > "$output" <<'M4A'

M4A
